def merge_sorted(a, b):
    result = []
    i = 0
    j = 0
    len_a = len(a)
    len_b = len(b)
    while i < len_a and j < len_b:
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    while i < len_a:
        result.append(a[i])
        i += 1
    while j < len_b:
        result.append(b[j])
        j += 1
    return result

def chunked(values, size):
    if size <= 0:
        raise ValueError("size must be a positive integer")
    return [values[i:i + size] for i in range(0, len(values), size)]

