def merge_tool_results(calls, results):
    # Reject duplicate call ids.
    calls_by_id = {}
    for call in calls:
        cid = call['id']
        if cid in calls_by_id:
            raise ValueError(f"Duplicate call id: {cid!r}")
        calls_by_id[cid] = call

    # Map id -> content, last result wins. Ignore unknown ids.
    content_by_id = {}
    for result in results:
        rid = result['id']
        if rid in calls_by_id:
            content_by_id[rid] = result.get('content', '')

    output = []
    for call in calls:
        cid = call['id']
        if cid in content_by_id:
            output.append({'id': cid, 'status': 'done', 'content': content_by_id[cid]})
        else:
            output.append({'id': cid, 'status': 'pending'})

    return output

