def summarize_usage(events):
    totals = {'input': 0, 'output': 0}
    per_request = {}
    for event in events:
        request_id = event['request_id']
        input_count = event.get('input', 0)
        output_count = event.get('output', 0)
        if input_count < 0 or output_count < 0:
            raise ValueError('token counts must be nonnegative')
        if request_id not in per_request:
            per_request[request_id] = {'input': 0, 'output': 0}
        per_request[request_id]['input'] = max(per_request[request_id]['input'], input_count)
        per_request[request_id]['output'] = max(per_request[request_id]['output'], output_count)
    for request_id in per_request:
        totals['input'] += per_request[request_id]['input']
        totals['output'] += per_request[request_id]['output']
    return totals

