def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for m in messages:
        if m["cost"] < 0:
            raise ValueError("cost must be nonnegative")

    n = len(messages)
    # Find the longest contiguous suffix whose total cost fits budget.
    # A suffix starting at index i includes messages[i..n-1].
    # We want the smallest i such that sum(messages[i..n-1]) <= budget.
    total = 0
    i = n
    while i > 0:
        if total + messages[i - 1]["cost"] <= budget:
            total += messages[i - 1]["cost"]
            i -= 1
        else:
            break
    return list(messages[i:])

