def summarize_usage(events):
    totals = {'input': 0, 'output': 0}
    maxes = {}
    for event in events:
        request_id = event['request_id']
        inp = event.get('input', 0)
        out = event.get('output', 0)
        if inp < 0 or out < 0:
            raise ValueError('negative count')
        prev = maxes.get(request_id)
        if prev is None:
            maxes[request_id] = (inp, out)
        else:
            maxes[request_id] = (max(prev[0], inp), max(prev[1], out))
    for request_id, (inp, out) in maxes.items():
        totals['input'] += inp
        totals['output'] += out
    return totals

