def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("budget must be nonnegative")
    for m in messages:
        if m["cost"] < 0:
            raise ValueError("cost must be nonnegative")

    n = len(messages)
    best = 0
    for start in range(n):
        total = 0
        for end in range(start, n):
            total += messages[end]["cost"]
            if total > budget:
                break
            length = end - start + 1
            if length > best:
                best = length
    return messages[n - best:]

