def merge_tool_results(calls, results):
    # Map id -> content, last result wins. Ignore unknown ids.
    content_by_id = {}
    for result in results:
        rid = result.get('id')
        if rid in content_by_id or rid is None:
            continue
        content_by_id[rid] = result.get('content', '')

    merged = []
    seen_ids = set()
    for call in calls:
        cid = call['id']
        if cid in seen_ids:
            raise ValueError('duplicate call id: %r' % (cid,))
        seen_ids.add(cid)
        if cid in content_by_id:
            merged.append({'id': cid, 'status': 'done', 'content': content_by_id[cid]})
        else:
            merged.append({'id': cid, 'status': 'pending'})

    return merged

